def _handle_notification_usage(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    """Per-channel notification usage view at ``GET /notification-usage``.

    The current notifications are grouped by their channel, one entry per
    channel ordered by its first appearance while resources are walked in
    registration order and each resource's notifications in submission
    order (redetermined from the remaining records after any
    deregistration). Each entry carries the six fixed keys ``channel``,
    ``notifications``, ``notification_count``, ``targets``, ``resources``
    and ``resource_count``: the channel echoed verbatim, the notification
    ids in submission order, that list's length, the targets deduplicated
    by first appearance, and the owning resources deduplicated in
    resource registration order with its count. Computed on the fly from
    the remaining records and recorded nowhere; notification
    registration and querying, the global summary and the per-channel
    filter keep their existing behavior.
    """

    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # Read-only: a declared non-empty (or malformed) body is a bad request
    # without consulting any business data. An omitted header and an
    # explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # No parameters whatsoever are accepted.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    usage = notification_store.usage_by_channel(
        [resource.id for resource in store.list_all()]
    )
    return _json_response(
        start_response,
        "200 OK",
        usage,
        trailing_newline=True,
    )


